SELECT compound_structures.canonical_smiles, molecule_dictionary.chembl_id, activities.standard_type, activities.standard_relation, activities.standard_value, activities.standard_units FROM assays JOIN activities ON assays.assay_id = activities.assay_id JOIN molecule_dictionary ON activities.molregno = molecule_dictionary.molregno JOIN compound_structures ON molecule_dictionary.molregno = compound_structures.molregno WHERE assays.chembl_id = 'CHEMBL1613797' AND activities.standard_value IS NOT NULL AND activities.standard_relation = '=' ORDER BY compound_structures.canonical_smiles ASC, molecule_dictionary.chembl_id ASC, activities.standard_type ASC, activities.standard_relation ASC, activities.standard_value ASC, activities.standard_units ASC
